import os
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Sequence, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class MetricComparisonResult:
    start_time: str
    end_time: str
    metric_name: str
    namespace: str
    statistic: str
    period: int
    resource_a: str
    resource_b: str
    value_a: Optional[float]
    value_b: Optional[float]
    delta: Optional[float]
    percent_change: Optional[float]
    raw_a: Dict[str, Any]
    raw_b: Dict[str, Any]


def _to_iso8601(value: Union[str, datetime]) -> str:
    if isinstance(value, datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.astimezone(timezone.utc).isoformat()
    return value


def _latest_datapoint(statistics: Dict[str, Any]) -> Optional[float]:
    timestamps = statistics.get("Timestamps") or []
    values = statistics.get("Values") or []
    if not timestamps or not values:
        return None
    try:
        latest_index = max(range(len(timestamps)), key=lambda i: timestamps[i])
        return float(values[latest_index])
    except Exception:
        return None


def _aggregate_datapoints(statistics: Dict[str, Any], statistic: str) -> Optional[float]:
    values = statistics.get("Values") or []
    if not values:
        return None

    try:
        stat = statistic.upper()
        numeric = [float(v) for v in values]
        if stat == "SUM":
            return float(sum(numeric))
        if stat == "AVERAGE":
            return float(sum(numeric) / len(numeric))
        if stat == "MINIMUM":
            return float(min(numeric))
        if stat == "MAXIMUM":
            return float(max(numeric))
        if stat == "SAMPLECOUNT":
            return float(len(numeric))
    except Exception:
        return None

    return _latest_datapoint(statistics)


def _build_dimension_stat_query(
    *,
    metric_name: str,
    namespace: str,
    dimensions: Dict[str, str],
    statistic: str,
    period: int,
    start_time: Union[str, datetime],
    end_time: Union[str, datetime],
    id_prefix: str,
) -> Dict[str, Any]:
    dim_list = [{"Name": k, "Value": v} for k, v in dimensions.items()]
    return {
        "Id": id_prefix,
        "MetricStat": {
            "Metric": {
                "Namespace": namespace,
                "MetricName": metric_name,
                "Dimensions": dim_list,
            },
            "Period": int(period),
            "Stat": statistic,
        },
        "ReturnData": True,
    }


def compare_cloudwatch_metrics(
    resource_a: str,
    resource_b: str,
    *,
    metric_name: str,
    namespace: str,
    statistic: str = "Average",
    period: int = 300,
    start_time: Union[str, datetime],
    end_time: Union[str, datetime],
    region_name: Optional[str] = None,
    dimension_name: Optional[str] = None,
    extra_dimensions_a: Optional[Dict[str, str]] = None,
    extra_dimensions_b: Optional[Dict[str, str]] = None,
) -> MetricComparisonResult:
    """
    Compare Amazon CloudWatch metric values for two resources or dimension filters over the same window.

    The comparison is performed using CloudWatch GetMetricData.
    By default, resource_a/resource_b are interpreted as values for a single dimension name
    (for example, InstanceId, LoadBalancer, AutoScalingGroupName, ClusterName, etc.).

    If dimension_name is None, resource_a and resource_b are treated as values for the dimension
    named "ResourceId" unless extra_dimensions_* explicitly provide full dimension filters.
    """
    region = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    client = boto3.client("cloudwatch", region_name=region)

    start_iso = _to_iso8601(start_time)
    end_iso = _to_iso8601(end_time)

    if extra_dimensions_a is None:
        extra_dimensions_a = {}
    if extra_dimensions_b is None:
        extra_dimensions_b = {}

    dim_key = dimension_name or "ResourceId"
    dims_a = {dim_key: resource_a, **extra_dimensions_a}
    dims_b = {dim_key: resource_b, **extra_dimensions_b}

    queries = [
        _build_dimension_stat_query(
            metric_name=metric_name,
            namespace=namespace,
            dimensions=dims_a,
            statistic=statistic,
            period=period,
            start_time=start_iso,
            end_time=end_iso,
            id_prefix="a",
        ),
        _build_dimension_stat_query(
            metric_name=metric_name,
            namespace=namespace,
            dimensions=dims_b,
            statistic=statistic,
            period=period,
            start_time=start_iso,
            end_time=end_iso,
            id_prefix="b",
        ),
    ]

    try:
        response = client.get_metric_data(
            MetricDataQueries=queries,
            StartTime=datetime.fromisoformat(start_iso.replace("Z", "+00:00")),
            EndTime=datetime.fromisoformat(end_iso.replace("Z", "+00:00")),
            ScanBy="TimestampDescending",
        )
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"CloudWatch metric comparison failed: {exc}") from exc

    results = {item["Id"]: item for item in response.get("MetricDataResults", [])}
    a_result = results.get("a", {})
    b_result = results.get("b", {})

    value_a = _aggregate_datapoints(a_result, statistic)
    value_b = _aggregate_datapoints(b_result, statistic)

    delta = None
    percent_change = None
    if value_a is not None and value_b is not None:
        delta = value_b - value_a
        if value_a != 0:
            percent_change = (delta / value_a) * 100.0

    return MetricComparisonResult(
        start_time=start_iso,
        end_time=end_iso,
        metric_name=metric_name,
        namespace=namespace,
        statistic=statistic,
        period=int(period),
        resource_a=resource_a,
        resource_b=resource_b,
        value_a=value_a,
        value_b=value_b,
        delta=delta,
        percent_change=percent_change,
        raw_a=a_result,
        raw_b=b_result,
    )
